Added the line that's commented as EXTRA. You can add lines for all the pics you need. That seemed to work for me, but I only tested it quickly back then.
_.loadAllImages = function() {
for (let property in _.backgrounds) {
if (_.backgrounds.hasOwnProperty(property)) {
const name = _.backgrounds[property];
if(name.trim().length > 0) {
_.loadImage(name);
}
}
}
_.loadImage("Sword"); // EXTRA
};
_.loadAllImages();

